package android.app;import android.content.*;import java.util.*;public class PendingIntent {public static final int FLAG_UPDATE_CURRENT=1,FLAG_IMMUTABLE=2;public static final Map<String,PendingIntent> all=new HashMap<>();public final String key;public Intent intent;private PendingIntent(String k,Intent i){key=k;intent=i;}public static PendingIntent getBroadcast(Context c,int n,Intent i,int flags){String k=n+":"+i.action+":"+i.component;PendingIntent p=all.get(k);if(p==null){p=new PendingIntent(k,i);all.put(k,p);}else if((flags&FLAG_UPDATE_CURRENT)!=0)p.intent=i;return p;}}
